with cleaned as (select id, store_id, quantity, last_restock, floor(quantity) as quantity_whole, cast(quantity as double) as quantity_num from inventory where last_restock > to_date('2023-03-23')) select case when quantity >= 228 then 'LARGE' else 'SMALL' end as quantity_tier, store_id, count(distinct store_id) as distinct_store_ids, approx_percentile(quantity_whole, 0.9) as quantity_whole_p90, count(distinct store_id) as distinct_store_ids_2, count(distinct store_id) as distinct_store_ids_3, round(avg(quantity), 2) as avg_quantity from cleaned group by case when quantity >= 228 then 'LARGE' else 'SMALL' end, store_id having distinct_store_ids_2 > 1 order by distinct_store_ids desc nulls last;
